23	impl RetryLogic for DatabendRetryLogic {
24	    type Error = DatabendError;
25	    type Response = DatabendResponse;
26	
27	    fn is_retriable_error(&self, error: &Self::Error) -> bool {
28	        match error {
29	            DatabendError::InvalidResponse(qe) => match qe.code {
30	                429 => true,
31	                // general server error
32	                500 => true,
33	                // storage doesn't support presign operation
34	                3902 => false,
35	                // fail to parse stage attachment
36	                1046 => false,
37	                _ => false,
38	            },
39	            DatabendError::IO(_) => true,
40	            _ => false,
41	        }
42	    }
43	}
