95	impl DatabendService {
96	    pub(super) fn new(
97	        client: DatabendAPIClient,
98	        table: String,
99	        file_format_options: BTreeMap<&'static str, &'static str>,
100	        copy_options: BTreeMap<&'static str, &'static str>,
101	    ) -> Result<Self, DatabendError> {
102	        if table.is_empty() {
103	            return Err(DatabendError::BadArgument("table is required".to_string()));
104	        }
105	        Ok(Self {
106	            client,
107	            table,
108	            file_format_options,
109	            copy_options,
110	        })
111	    }
112	
113	    async fn new_stage_location(&self) -> String {
114	        let now = Utc::now().timestamp();
115	        let database = self
116	            .client
117	            .current_database()
118	            .await
119	            .unwrap_or("default".to_string());
120	        let suffix = rng()
121	            .sample_iter(&Alphanumeric)
122	            .take(8)
123	            .map(char::from)
124	            .collect::<String>();
125	        format!("@~/vector/{}/{}/{}-{}", database, self.table, now, suffix,)
126	    }
127	
128	    pub(crate) async fn insert_with_stage(&self, data: Bytes) -> Result<(), DatabendError> {
129	        let stage = self.new_stage_location().await;
130	        let size = data.len() as u64;
131	        let reader = Box::new(Cursor::new(data));
132	        self.client.upload_to_stage(&stage, reader, size).await?;
133	        let sql = format!("INSERT INTO `{}` VALUES", self.table);
134	        let _ = self
135	            .client
136	            .insert_with_stage(
137	                &sql,
138	                &stage,
139	                self.file_format_options.clone(),
140	                self.copy_options.clone(),
141	            )
142	            .await?;
143	        Ok(())
144	    }
145	}
146	
147	impl Service<DatabendRequest> for DatabendService {
148	    type Response = DatabendResponse;
149	    type Error = DatabendError;
150	    type Future = BoxFuture<'static, Result<Self::Response, Self::Error>>;
151	
152	    fn poll_ready(&mut self, _cx: &mut Context) -> Poll<Result<(), Self::Error>> {
153	        Poll::Ready(Ok(()))
154	    }
155	
156	    fn call(&mut self, request: DatabendRequest) -> Self::Future {
157	        let service = self.clone();
158	
159	        let future = async move {
160	            let metadata = request.get_metadata().clone();
161	            let protocol = service.client.scheme.as_str();
162	            let host_port = format!("{}:{}", service.client.host, service.client.port);
163	            let endpoint = host_port.as_str();
164	            let byte_size = request.data.len();
165	            service.insert_with_stage(request.data).await?;
166	            emit!(EndpointBytesSent {
167	                byte_size,
168	                protocol,
169	                endpoint,
170	            });
171	            Ok(DatabendResponse { metadata })
172	        };
173	        Box::pin(future)
174	    }
175	}
