9	    service: Svc<DatabendService, DatabendRetryLogic>,
10	}
11	
12	impl DatabendSink {
13	    pub(super) const fn new(
14	        batch_settings: BatcherSettings,
15	        request_builder: DatabendRequestBuilder,
16	        service: Svc<DatabendService, DatabendRetryLogic>,
17	    ) -> Self {
18	        Self {
19	            batch_settings,
20	            request_builder,
21	            service,
22	        }
23	    }
24	
25	    async fn run_inner(self: Box<Self>, input: BoxStream<'_, Event>) -> Result<(), ()> {
26	        input
27	            .batched(self.batch_settings.as_byte_size_config())
28	            .request_builder(
29	                default_request_builder_concurrency_limit(),
30	                self.request_builder,
31	            )
32	            .filter_map(|request| async move {
33	                match request {
34	                    Err(error) => {
35	                        emit!(SinkRequestBuildError { error });
36	                        None
37	                    }
38	                    Ok(req) => Some(req),
39	                }
40	            })
41	            .into_driver(self.service)
42	            .run()
43	            .await
44	    }
45	}
